from html.parser import HTMLParser
from pathlib import Path
import hashlib, json, re

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.hidden = max(0, self.hidden - 1)
    def handle_data(self, data):
        if not self.hidden and data.strip():
            self.parts.append(data.strip())

root = Path('products/distribution/sqlite-lemon-squeezy')
patterns = {
    'supported-countries': r'\bCanada\b|bank payout|PayPal payout|payout methods',
    'prohibited-products': r'\bservices?\b|\bsoftware\b|digital (?:goods|products|downloads)|\blicens\w*\b|artificial intelligence|\bAI\b',
}
results = []
for slug, pattern in patterns.items():
    source = root / 'raw' / (slug + '.html')
    raw = source.read_bytes()
    parser = VisibleText()
    parser.feed(raw.decode('utf-8'))
    text = re.sub(r'\s+', ' ', ' '.join(parser.parts))
    matches = list(re.finditer(pattern, text, re.I))
    excerpts = [text[max(0, match.start() - 160):match.end() + 200] for match in matches[:40]]
    results.append({'source_url': 'https://docs.lemonsqueezy.com/help/getting-started/' + slug, 'capture': str(source), 'sha256': hashlib.sha256(raw).hexdigest(), 'match_count': len(matches), 'navigation_included': True, 'excerpts': excerpts})
output = root / 'director-policy-excerpts.json'
output.write_text(json.dumps({'scope': 'Text screening only. Read each governing passage in its original context before an eligibility decision. No activation or payout verified.', 'sources': results}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(output), 'counts': [r['match_count'] for r in results]}))
